'use strict';
const $=id=>document.getElementById(id);
const esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>typeof x==='number'&&Number.isFinite(x)?x.toFixed(4):'—';
const percent=x=>typeof x==='number'?(x*100).toFixed(1)+'%':'—';
const pretty=x=>String(x).replaceAll('_',' ');
const time=x=>x?new Date(x).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}):'Not available';
const table=(heads,rows)=>'<div class="table-scroll"><table><thead><tr>'+heads.map(h=>'<th>'+esc(h)+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';
const SPORT_INFO={
 NBA:{title:'NBA Basketball',kicker:'BASKETBALL / NBA',description:'Team strength, rolling scoring margins and rest. Historical validation is separate from current availability.',needs:'Opponent-adjusted efficiency, shooting, turnovers, rebounds, possessions, rest and player availability.'},
 NFL:{title:'NFL Football',kicker:'FOOTBALL / NFL',description:'Result-based team strength and recent performance. Win probabilities are conditional on a decisive outcome.',needs:'EPA, success rate, quarterback performance, offensive/defensive efficiency, injuries, rest and weather.'},
 NHL:{title:'NHL Hockey',kicker:'HOCKEY / NHL',description:'Eventual-winner results, rating strength and recent scoring. Goalies and expected goals remain unconfirmed.',needs:'Expected goals, shot quality, special teams, starting goalies, goalie performance and rest.'},
 CFB:{title:'College Football',kicker:'FOOTBALL / NCAA',description:'A dedicated data and validation view. Forecasts stay unavailable until reliable history is loaded and tested.',needs:'Opponent- and schedule-adjusted efficiency, EPA, success rate, quarterback strength and injuries; college schedules require special care.'},
 WNBA:{title:'WNBA Basketball',kicker:'BASKETBALL / WNBA',description:'Separate league, data requirements and validation. No NBA probabilities are reused as WNBA forecasts.',needs:'Possession-adjusted offensive/defensive efficiency, pace, shooting, turnovers, rebounding, rest and availability.'},
 MLB:{title:'MLB Baseball',kicker:'BASEBALL / MLB',description:'Regular-season and postseason history. This baseline does not claim a starting-pitcher or confirmed-lineup edge.',needs:'Starting-pitcher strikeout/walk rates, handedness, batting strength, bullpen quality/workload, park factors, weather and lineups.'},
 UFC:{title:'UFC Mixed Martial Arts',kicker:'COMBAT SPORTS / UFC',description:'Fighter-specific data and validation are required. No raw career-win-rate shortcut is presented as a trained model.',needs:'Opponent strength, striking/grappling, takedowns and defense, age, reach, weight class, layoffs and scheduled fight length.'}
};
const localDay=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const shiftDay=(day,n)=>{const d=new Date(day+'T12:00:00');d.setDate(d.getDate()+n);return localDay(d);};
const dayLabel=day=>new Date(day+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'});
let snapshot=null,league='NFL',view=new URLSearchParams(location.search).get('view')==='finder'?'finder':'forecasts',selected=null,dateFilter=localDay(),teamFilter='',allSports=false,followToday=true;
try{league=localStorage.getItem('courtside_public_league')||'NFL';}catch(_){}
const expired=p=>Date.now()>=Date.parse(p.valid_until)||Date.now()>=Date.parse(snapshot.valid_until);
const active=l=>(l.predictions||[]).filter(p=>!expired(p));
const freshFeed=l=>l.feed_status==='fresh'&&Date.now()<Date.parse(snapshot.valid_until)&&Date.now()-Date.parse(l.feed_checked)<=86400000;
const eventDay=p=>{const start=p.event_start_utc||p.start_time;return start?localDay(new Date(start)):p.date;};
const fixtures=l=>freshFeed(l)?(l.schedule||[]).filter(p=>p.start_time?Date.parse(p.start_time)>Date.now():p.date>=localDay()):[];
const dayEvents=l=>freshFeed(l)?(l.schedule||[]).filter(p=>eventDay(p)===dateFilter):[];
const rawHistory=l=>(l.prediction_history||[]).filter(p=>eventDay(p)>=shiftDay(localDay(),-6)&&eventDay(p)<=localDay());
const history=l=>uniquePredictions(rawHistory(l),l.lifecycle?.feedback_policy);
const daySports=()=>snapshot.leagues.filter(l=>view==='history'?history(l).length:dayEvents(l).length||active(l).some(p=>eventDay(p)===dateFilter)||history(l).some(p=>eventDay(p)===dateFilter));
function chooseDay(day){dateFilter=day||localDay();followToday=dateFilter===localDay();selected=null;render();}
function current(){return snapshot.leagues.find(l=>l.name===league)||snapshot.leagues[0];}
function safeLink(url){try{const u=new URL(url);return u.protocol==='https:'?esc(u.href):'#';}catch(_){return '#';}}
function empty(title,body){return `<div class="empty"><strong>${esc(title)}</strong><p>${esc(body)}</p></div>`;}
const WORKFLOW_URL='https://github.com/cbegalla111/sportsMLmodel/actions/workflows/pages.yml';
const WORKFLOW_API='https://api.github.com/repos/cbegalla111/sportsMLmodel/actions/workflows/pages.yml/runs?branch=main&per_page=1';
let runStatusLoading=false,lastRun=null;
function nextUpdate(now=new Date()){
 const schedule=snapshot?.refresh_schedule||{utc_hours:Array.from({length:24},(_,i)=>i),minute:17};
 const slots=[0,1].flatMap(offset=>schedule.utc_hours.map(hour=>new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth(),now.getUTCDate()+offset,hour,schedule.minute))));
 return slots.filter(d=>d>now).sort((a,b)=>a-b)[0];
}
async function loadRunStatus(){
 if(runStatusLoading)return;runStatusLoading=true;
 const status=$('pipeline-status');
 try{
  const response=await fetch(WORKFLOW_API,{headers:{Accept:'application/vnd.github+json'},cache:'no-store',signal:AbortSignal.timeout(12000)});
  if(!response.ok)throw Error('GitHub status unavailable');
  const run=(await response.json()).workflow_runs?.[0];if(!run)throw Error('No update runs');
  status.href=/^https:\/\/github\.com\/cbegalla111\/sportsMLmodel\/actions\/runs\/\d+$/.test(run.html_url)?run.html_url:WORKFLOW_URL;
  status.textContent=run.status==='completed'?(run.conclusion==='success'?'Latest data update completed ↗':'Latest update needs attention ↗'):run.status==='in_progress'?'Data update running… ↗':'Data update queued… ↗';
  if(run.status==='completed'&&run.conclusion==='success'&&lastRun&&(lastRun.id!==run.id||lastRun.status!=='completed'))await load();
  lastRun={id:run.id,status:run.status};
 }catch(_){status.href=WORKFLOW_URL;status.textContent='View update status on GitHub ↗';}
 finally{runStatusLoading=false;}
}
function render(){
 if(followToday)dateFilter=localDay();
 const playing=daySports();if(!allSports&&playing.length&&!playing.some(s=>s.name===league))league=playing[0].name;
 const l=current();league=l.name;const info=SPORT_INFO[league],report=l.benchmark,forecasts=active(l).filter(p=>eventDay(p)===dateFilter),overdue=Date.now()>=Date.parse(snapshot.valid_until);
 $('dashboard').hidden=false;$('loading').hidden=true;$('updated').textContent='Updated '+time(snapshot.generated_at);$('refresh-detail').textContent='Next scheduled update: '+time(nextUpdate().toISOString());
 $('day-summary').textContent=view==='history'?`Past 7 days · ${playing.length} sports with saved predictions · Times in ${Intl.DateTimeFormat().resolvedOptions().timeZone}.`:`${dayLabel(dateFilter)} · ${playing.length} scheduled sports · Times in ${Intl.DateTimeFormat().resolvedOptions().timeZone}. Future schedules appear as feeds publish them.`;
 $('forecast-title').textContent=dateFilter<localDay()?'Saved predictions for selected day':'Predictions for selected day';$('yesterday').classList.toggle('selected',dateFilter===shiftDay(localDay(),-1));
 $('today').classList.toggle('selected',dateFilter===localDay());$('tomorrow').classList.toggle('selected',dateFilter===shiftDay(localDay(),1));
 $('all-sports').checked=allSports;
 const futureDays=[...new Set(snapshot.leagues.flatMap(s=>fixtures(s).map(eventDay)))].sort();$('future-dates').innerHTML='<option value="">Choose a published date</option>'+futureDays.map(d=>`<option value="${d}">${esc(dayLabel(d))} · ${d}</option>`).join('');if(futureDays.includes(dateFilter))$('future-dates').value=dateFilter;$('next-game-day').disabled=!fixtures(l).length;
 $('day-options').innerHTML=Array.from({length:7},(_,i)=>{const day=shiftDay(localDay(),i);const count=snapshot.leagues.filter(s=>freshFeed(s)&&(s.schedule||[]).some(p=>eventDay(p)===day)).length;return `<button type="button" data-day="${day}" class="${dateFilter===day?'selected':''}">${esc(dayLabel(day))}<small>${count} sports</small></button>`;}).join('');
 $('sports').innerHTML=(!allSports&&!playing.length?'<p class="muted">'+(view==='history'?'No saved picks in the past week yet. Enable All sports to browse each league.':'No scheduled sports returned for this day. Choose another date or enable All sports to browse model history.')+'</p>':'')+(allSports?snapshot.leagues:playing).map(s=>`<button data-league="${s.name}" type="button" class="${s.name===league?'selected':''}"><span class="sport-dot ${active(s).length?'ready':''}"></span>${s.name} <small>${view==='history'?history(s).length+' picks':dayEvents(s).length+' events'}</small></button>`).join('');
 $('sport-kicker').textContent=info.kicker;$('sport-title').textContent=info.title;$('sport-description').textContent=info.description;
 $('readiness').textContent=forecasts.length?'Predictions ready':report?'Model ready':'Building model history';$('readiness').className='tag'+(!forecasts.length?' warn':'');
 $('freshness-alert').textContent=overdue?'Update overdue. Current probabilities are withheld until a successful refresh publishes a new snapshot. Historical results remain available.':l.limitation;$('freshness-alert').className='status-banner'+(!forecasts.length||overdue?' warn':'');
 $('result-count').textContent=l.result_count.toLocaleString();$('coverage').textContent=l.data_from?`${l.data_from} → ${l.data_through}`:'No verified public history loaded';
 $('forecast-count').textContent=forecasts.length;$('brier').textContent=report?percent(report.test.accuracy):'—';$('test-sample').textContent=report?`${report.test.n.toLocaleString()} held-out events · historical`:'No evaluation available';$('data-through').textContent=l.data_through||'No data';$('feed-note').textContent=l.feed_checked?`Feed ${freshFeed(l)?'updated':'update pending'} · ${time(l.feed_checked)}`:'No verified current feed';
 for(const name of ['forecasts','history','models','data','props','finder','perfect'])$('view-'+name).hidden=view!==name;
 const guide={perfect:['100% observed hit rates','Historical player-prop scans across all teams, with exact samples and supporting results.'],forecasts:['Game forecasts','Choose a day and sport, then select a matchup to inspect the prediction and its factors.'],history:['Prediction record','See saved pre-game picks, verified final results and recent correct / incorrect totals.'],finder:['Best props for the day','Choose a count and compare ranked props across all games on the selected day.'],props:['Player game logs','Inspect individual performances and test a line against collected appearances.'],models:['Models & accuracy','Review the active model, historical benchmarks and separate improvement experiments.'],data:['Data & injuries','Check source coverage, refresh times, reported injuries and available teams.']}[view];
 $('view-title').textContent=guide[0];$('view-description').textContent=guide[1];
 document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===view);b.setAttribute('aria-current',b.dataset.view===view?'page':'false');});
 $('outcome-rules').textContent=snapshot.rules;$('date-filter').value=dateFilter;
 const filtered=forecasts.filter(p=>(!dateFilter||eventDay(p)===dateFilter)&&(!teamFilter||(p.home+' '+p.away).toLowerCase().includes(teamFilter.toLowerCase())));
 if(!filtered.some(p=>p.id===selected))selected=filtered[0]?.id||null;
 $('matchups').innerHTML=filtered.length?filtered.map(p=>{const home=p.home_probability>=p.away_probability,winner=home?p.home:p.away,loser=home?p.away:p.home,prob=Math.max(p.home_probability,p.away_probability);return `<button class="matchup-card ${p.id===selected?'selected':''}" type="button" data-fixture="${esc(p.id)}"><div class="matchup-meta"><span>${p.event_start_utc?esc(time(p.event_start_utc)):esc(p.date)+' · DATE ONLY'}</span><span>${p.injury_context?.status==='review_required'?'INJURY REVIEW · BASELINE':'RESULT-HISTORY BASELINE'}</span></div><div class="matchup-teams"><div class="team-name">${esc(winner)}<small>Most likely winner · conditional probability</small></div><div class="matchup-prob">${percent(prob)}</div></div><div class="runner-up"><span>${esc(loser)}</span><span>${percent(1-prob)}</span></div><div class="prob-track"><span></span></div><div class="card-foot"><span>${esc(pretty(p.model))}</span><span>Inspect factors ↗</span></div></button>`;}).join(''):empty(dateFilter||teamFilter?'No matching predictions':'Predictions pending',dateFilter||teamFilter?'Try another team or date.':'Upcoming fixtures and recent results are listed below.');
 // CSSOM assignment avoids requiring unsafe-inline in the content security policy.
 $('matchups').querySelectorAll('.prob-track span').forEach((b,i)=>{const p=filtered[i];b.removeAttribute('style');b.style.width=(100*Math.max(p.home_probability,p.away_probability))+'%';});
 const prediction=filtered.find(p=>p.id===selected);renderDetail(prediction,l);$('why-content').innerHTML=explainPrediction(prediction,l);$('record-overview').innerHTML=recordOverview(l);
 const withheld=[...(l.withheld||[]),...(l.predictions||[]).filter(expired).map(p=>({...p,reason:'Forecast expired; current probability withheld.'}))].filter(p=>{const fixture=(l.schedule||[]).find(f=>f.home===p.home&&f.away===p.away&&f.date===p.date);return eventDay(fixture||p)===dateFilter&&(!teamFilter||(p.home+' '+p.away).toLowerCase().includes(teamFilter.toLowerCase()));});
 $('withheld-details').hidden=!withheld.length;$('withheld-summary').textContent=withheld.length+' fixtures with forecasts withheld — see reasons';$('withheld-list').innerHTML=table(['Date','Matchup','Reason'],withheld.map(w=>[w.date,w.home+' / '+w.away,w.reason]));
 document.querySelector('.forecast-grid').hidden=dateFilter<localDay();
 renderHistory(l);if(view==='perfect')renderPerfectProps();if(view==='finder')renderFinder();if(view==='props')renderProps();if(view==='models')renderModels(l);if(view==='data')renderData(l);renderStatus(l);
}
function historyTable(picks,l){
 if(!picks.length)return empty('No saved pre-game predictions for this period','History builds only from predictions actually published before a game.');
 const counts=predictionCounts(picks);
 const labels={graded:'Graded',pending:'Awaiting final',in_progress:'In progress',awaiting_result:'Awaiting source result',unscored:'Unscored',not_pregame:'Unscored · published after verified start',canceled:'Canceled · unscored',postponed:'Postponed · unscored'};
 return `<p class="muted">${picks.length} saved picks · ${counts.correct} correct / ${counts.graded} graded${counts.graded?' · '+percent(counts.accuracy)+' accuracy':''}. Draws, cancellations and entries published after a corrected official start are not scored as wins or losses.</p>`+table(['Event date / time','Matchup','Predicted winner','Saved probability','Final result','Pick result','Result status','Prediction policy','Published'],picks.map(p=>{const home=p.home_probability>=.5,category=resultCategory(p);const outcome=p.outcome==='home'?p.home:p.outcome==='away'?p.away:p.outcome?pretty(p.outcome):'No verified final yet';return [p.event_start_utc?time(p.event_start_utc):p.date+' (source date)',p.home+' / '+p.away,home?p.home:p.away,percent(home?p.home_probability:p.away_probability),outcome+(p.outcome&&l.name!=='UFC'&&p.home_score!=null&&p.away_score!=null?' · '+p.home_score+' – '+p.away_score:''),{correct:'Correct',incorrect:'Incorrect',pending:'Pending',awaiting:'Awaiting source',unscored:'Unscored',scheduled:'Scheduled'}[category],labels[p.result_status]||pretty(p.result_status||category),p.prediction_policy||'legacy rest policy',time(p.generated_at)];}));
}
function renderHistory(l){
 const picks=history(l).filter(p=>!teamFilter||(p.home+' '+p.away).toLowerCase().includes(teamFilter.toLowerCase()));
 $('history-content').innerHTML='<h3>Prediction record · '+esc(l.name)+'</h3><p class="muted">'+esc(dayLabel(shiftDay(localDay(),-6)))+' – '+esc(dayLabel(localDay()))+' · saved pre-game predictions and imported final results. Pending results settle with hourly data updates.</p>'+historyTable(picks,l)+'<details><summary>Audit all original prediction policies · duplicate event versions</summary>'+historyTable(rawHistory(l),l)+'</details>'+diagnosticsPanel(l);
 $('day-history').hidden=dateFilter>=localDay();
 $('day-history').innerHTML='<h3>Saved predictions · '+esc(dayLabel(dateFilter))+'</h3>'+historyTable(picks.filter(p=>eventDay(p)===dateFilter),l);
}
function renderDetail(p,l){
 if(!p){$('matchup-detail').innerHTML=`<h3>Matchup details</h3><p class="muted">Select a prediction to see both opponents’ probabilities and the model inputs. Schedules and final results remain available below.</p>`;return;}
 const factors=[...p.factors].sort((a,b)=>Math.abs(b.log_odds_contribution||0)-Math.abs(a.log_odds_contribution||0));const scale=Math.max(...factors.map(f=>Math.abs(f.log_odds_contribution||0)),.01);
 $('matchup-detail').innerHTML=`<p class="eyebrow">SELECTED MATCHUP / MODEL FACTORS</p><div class="detail-title"><span>${esc(p.home)}</span><span>${esc(p.away)}</span></div><div class="detail-probs"><div><strong>${percent(p.home_probability)}</strong><span>Home / first opponent</span></div><div><strong>${percent(p.away_probability)}</strong><span>Away / second opponent</span></div></div><div class="prob-track"><span></span></div><p class="muted">${esc(p.mode)} · ${esc(p.date)}. Conditional on a decisive eventual winner.</p>${p.rest_context?`<h4>Rest in this sport</h4><p class="muted">${esc(p.rest_context.note)}</p>${table(['Opponent','Days since recorded event'],[[p.home,p.rest_context.home_gap_days??'Unknown'],[p.away,p.rest_context.away_gap_days??'Unknown']])}<p class="muted">Typical spacing: ${p.rest_context.typical_days} days · Recovery credit capped at ${p.rest_context.recovery_cap_days} days · Long inactivity threshold: ${p.rest_context.inactive_after_days} days. Adjusted recovery difference: ${p.rest_context.recovery_difference} ${esc(p.rest_context.unit)}. Schedule-based context; individual recovery and injuries are unconfirmed.</p>`:''}<h4>What the fitted model uses</h4>${factors.map(f=>`<div class="factor"><div class="factor-line"><span>${esc(pretty(f.factor))}</span><b>${typeof f.log_odds_contribution==='number'?(f.log_odds_contribution>=0?'+':'')+f.log_odds_contribution.toFixed(3)+' log odds':'Input '+num(f.difference)}</b></div><div class="factor-track ${(f.log_odds_contribution||0)<0?'negative':''}"><span></span></div></div>`).join('')}<p class="muted">${factors.some(f=>typeof f.log_odds_contribution==='number')?`Positive contributions favor ${esc(p.home)}; negative contributions favor ${esc(p.away)}. These explain fitted log odds, not causation.`:'These are raw input differences. This model does not expose a direct per-input log-odds breakdown.'}</p><details><summary>Raw model inputs & audit trail</summary>${table(['Factor','Home − away input','Log-odds contribution'],p.factors.map(f=>[pretty(f.factor),num(f.difference),num(f.log_odds_contribution)]))}<p class="audit-line">Source-verified event start<strong>${esc(time(p.event_start_utc))}</strong></p><p class="audit-line">Generated<strong>${esc(time(p.generated_at))}</strong></p><p class="audit-line">Data through<strong>${esc(p.data_through)}</strong></p><p class="audit-line">Valid until<strong>${esc(time(p.valid_until))}</strong></p><p class="audit-line">Training data SHA-256<strong>${esc(p.dataset_sha256)}</strong></p><p class="audit-line">Schedule source<strong><a href="${safeLink(p.schedule_source)}" target="_blank" rel="noopener">${esc(p.schedule_source)}</a></strong></p></details><p class="muted">${esc(p.availability)}</p>`;
 $('matchup-detail').querySelector('.prob-track span').style.width=(100*p.home_probability)+'%';$('matchup-detail').querySelectorAll('.factor-track span').forEach((b,i)=>b.style.width=(100*Math.abs(factors[i].log_odds_contribution||0)/scale)+'%');
}
function calibration(bins){return `<div class="calibration"><svg viewBox="0 0 430 280" role="img" aria-label="Calibration: mean predicted probability versus observed win frequency"><text x="48" y="15">Observed home-win frequency</text>${[0,.25,.5,.75,1].map(t=>`<line class="grid" x1="45" y1="${240-210*t}" x2="405" y2="${240-210*t}"/><text x="15" y="${244-210*t}">${t}</text><text x="${40+360*t}" y="257">${t}</text>`).join('')}<line class="reference" x1="45" y1="240" x2="405" y2="30"/><polyline points="${bins.map(b=>`${45+360*b.predicted},${240-210*b.observed}`).join(' ')}"/>${bins.map(b=>`<circle cx="${45+360*b.predicted}" cy="${240-210*b.observed}" r="4"><title>${esc('n='+b.n+'; forecast '+percent(b.predicted)+'; observed '+percent(b.observed))}</title></circle>`).join('')}<text x="142" y="277">Mean predicted home-win probability</text></svg></div>`;}
function reviewPanel(l){
 const r=l.lifecycle?.backtest_review;if(!r)return '';
 return `<section class="panel limits-panel"><div class="section-heading"><div><h3>Latest model backtest review</h3><p class="muted">${esc(time(r.checked))} · ${r.completed_candidates??r.candidate_count}/${r.candidate_count} challengers evaluated · three expanding folds · ${esc(r.status)}</p></div><span class="tag subdued">DEVELOPMENT RESULTS</span></div>${table(['Model','Accuracy','Log loss','Brier','Events'],[[pretty(r.incumbent.name),percent(r.incumbent.validation.accuracy),num(r.incumbent.validation.log_loss),num(r.incumbent.validation.brier),r.incumbent.validation.n],[pretty(r.best.name),percent(r.best.validation.accuracy),num(r.best.validation.log_loss),num(r.best.validation.brier),r.best.validation.n],...(r.accuracy_leader&&r.accuracy_leader.name!==r.best.name?[[pretty(r.accuracy_leader.name)+' · highest development accuracy',percent(r.accuracy_leader.validation.accuracy),num(r.accuracy_leader.validation.log_loss),num(r.accuracy_leader.validation.brier),r.accuracy_leader.validation.n]]:[])])}${r.rest_policy_review?`<details><summary>Rest correction backtest · same fitted coefficients</summary>${table(['Policy','Accuracy','Log loss','Brier'],[['Previous generic rest',percent(r.rest_policy_review.before.validation.accuracy),num(r.rest_policy_review.before.validation.log_loss),num(r.rest_policy_review.before.validation.brier)],['Sport-specific recovery limits',percent(r.rest_policy_review.after.validation.accuracy),num(r.rest_policy_review.after.validation.log_loss),num(r.rest_policy_review.after.validation.brier)]])}<p class="muted">This isolates the recovery-input correction. It can improve or worsen an individual metric; a higher overall model accuracy is not assumed. New learned challengers still require independent confirmation.</p></details>`:''}${r.best.validation.calibration_error!==undefined?table(['Metric','Incumbent','Selected'],[['Calibration error',num(r.incumbent.validation.calibration_error),num(r.best.validation.calibration_error)],['Balanced accuracy',percent(r.incumbent.validation.balanced_accuracy),percent(r.best.validation.balanced_accuracy)],['Precision (home/first opponent)',percent(r.incumbent.validation.precision),percent(r.best.validation.precision)],['Recall (home/first opponent)',percent(r.incumbent.validation.recall),percent(r.best.validation.recall)]]):''}<p class="muted">${esc(r.note)}</p>${r.previous_search?`<p class="muted">Previous research winner: ${esc(pretty(r.previous_search.name))} · ${percent(r.previous_search.validation.accuracy)} accuracy. New selected candidate: ${percent(r.best.validation.accuracy)} · ${(100*r.previous_search.accuracy_gain).toFixed(2)} percentage-point change on the same development games. ${esc(r.previous_search.note)}</p>`:''}${r.selection_objective?`<p class="muted">${esc(r.selection_objective)}</p>`:''}${r.fold_policy?`<p class="muted">${esc(r.fold_policy)}</p>`:''}${r.fit_error?`<p class="muted">Candidate fitting pending: ${esc(r.fit_error)}</p>`:''}${r.comparison_uncertainty?`<p class="muted">Development accuracy change: ${r.comparison_uncertainty.accuracy_gain_95.map(v=>(100*v).toFixed(2)).join(' to ')} percentage points; log-loss change: ${r.comparison_uncertainty.log_loss_delta_95.map(v=>v.toFixed(4)).join(' to ')} (approximate 95% weekly intervals). ${esc(r.comparison_uncertainty.note)}</p>`:''}<details><summary>All challengers and chronological folds</summary>${table(['Candidate','Accuracy','Log loss','Brier','Status'],[...r.candidates].sort((a,b)=>(b.validation?.accuracy??-1)-(a.validation?.accuracy??-1)||(a.validation?.log_loss??Infinity)-(b.validation?.log_loss??Infinity)).map(c=>[pretty(c.name),percent(c.validation?.accuracy),num(c.validation?.log_loss),num(c.validation?.brier),c.reason||c.status||'completed']))}${table(['Training/calibration ends','Inner calibration block','Validation starts','Validation ends','Events'],r.best.folds.map(f=>[f.train_end,f.calibration?f.calibration.calibration_start+' → '+f.calibration.calibration_end+' (n='+f.calibration.calibration_n+')':'Not used',f.validation_start,f.validation_end,f.n]))}</details></section>`;
}
function nbaTargetPanel(l){
 const b=l.lifecycle?.nba_box_research;if(l.name!=='NBA'||!b?.confirmation)return '';
 const m=b.target_reference.validation;
 return `<section class="panel limits-panel"><h3>NBA accuracy target</h3><p>Historical confirmation: <strong>${percent(m.accuracy)}</strong> · Target: <strong>${percent(b.target_accuracy)}</strong> · ${b.additional_correct_needed} more correct picks needed on the same ${m.n.toLocaleString()} games.</p><p class="muted">${b.completed_candidates}/${b.candidate_count} additional candidates tested with prior-game shooting, turnovers, rebounding, free throws and estimated possession efficiency. ${b.target_reached?'The historical target was reached; live performance still requires independent evidence.':'The 70% target has not been verified. The current candidate is retained.'} These experimental inputs do not change live forecasts or locked trials.</p><details><summary>Box-score research and source checks</summary><p class="muted">${b.source_matched_games.toLocaleString()} result-matched box-score games · ${b.box_confirmation_games} confirmation games with boxes. Source check: ${esc(b.source_status.status)} · ${esc(time(b.source_status.checked))}. ${esc(b.note)}</p>${table(['Historical confirmation','Accuracy','Log loss','Brier'],[['Retained feedback candidate',percent(b.confirmation.previous.validation.accuracy),num(b.confirmation.previous.validation.log_loss),num(b.confirmation.previous.validation.brier)],['Development-selected box-score experiment',percent(b.confirmation.selected.validation.accuracy),num(b.confirmation.selected.validation.log_loss),num(b.confirmation.selected.validation.brier)]])}${table(['Development candidate','Accuracy','Log loss','Brier','Status'],b.candidates.map(c=>[pretty(c.name),percent(c.validation?.accuracy),num(c.validation?.log_loss),num(c.validation?.brier),c.status||c.reason]))}</details></section>`;
}
function nbaLearningPanel(l){
 if(l.name!=='NBA'||!l.lifecycle)return '';
 const c=l.lifecycle,f=c.feedback_report,t=c.nba_feedback_trial,a=c.backtest_review?.later_era_audit,r=c.nba_recent_review;
 return `<section class="panel limits-panel"><h3>NBA prediction feedback</h3>${f?.metrics?`<p>Saved pregame picks: <strong>${percent(f.metrics.accuracy)}</strong> correct across ${f.n} settled games. Approximate accuracy range: ${f.accuracy_95.map(percent).join('–')}.</p><p class="muted">Log loss ${num(f.metrics.log_loss)} · Brier ${num(f.metrics.brier)}. This is the live saved-pick record, separate from historical model research. ${esc(f.note)}</p><details><summary>Confidence and missed predictions</summary>${table(['Predicted confidence','Games','Mean confidence','Actual correct'],f.confidence_bands.map(b=>[percent(b.from)+'–'+percent(b.to),b.n,percent(b.mean_confidence),percent(b.accuracy)]))}${table(['Source date','Predicted winner','Confidence','Actual winner'],f.largest_misses.map(p=>[p.date,p.home_probability>=.5?p.home:p.away,percent(Math.max(p.home_probability,1-p.home_probability)),p.outcome==='home'?p.home:p.away]))}</details>`:'<p class="muted">Saved pregame picks are scored when final results arrive.</p>'}${t?`<h4>New NBA candidate</h4><p>${esc(pretty(t.selected))} · ${esc(t.status)}</p><p class="muted">Locked before results after ${esc(t.after)}. Weights fitted through ${esc(t.weights_through)}. ${t.confirmation?t.confirmation.n+'/'+c.policy.minimum_results+' new results across '+t.confirmation.weeks+'/'+c.policy.minimum_weeks+' calendar weeks.':''} The same independent accuracy, log-loss and Brier checks apply before promotion. ${t.status==='collecting evidence'?'The earlier trial remains intact while this candidate is evaluated.':'The independent review has finished.'}</p>`:''}${r?.confirmation?`<h4>Recent-data model check</h4><p class="muted">${esc(pretty(r.selected))} · ${r.completed_candidates}/${r.candidate_count} candidates evaluated. Selection data: ${esc(r.history_from)} through June 2025. Confirmation: ${esc(r.confirmation.from)} to before ${esc(r.confirmation.before)}.</p>${table(['Same recent training history','Correct winners','Log loss','Brier','Games'],[['Previous specification',percent(r.confirmation.previous.validation.accuracy),num(r.confirmation.previous.validation.log_loss),num(r.confirmation.previous.validation.brier),r.confirmation.previous.validation.n],['Feedback specification',percent(r.confirmation.selected.validation.accuracy),num(r.confirmation.selected.validation.log_loss),num(r.confirmation.selected.validation.brier),r.confirmation.selected.validation.n]])}<p class="muted">${esc(r.confirmation.note)} ${r.confirmation.passed?'Passed historical accuracy and probability-score checks; awaiting independent live evidence.':'Historical comparison did not pass every check.'}</p>`:''}${a?`<details><summary>Prior-specification three-season audit</summary><p class="muted">${esc(a.from)} to before ${esc(a.before)} · ${esc(a.note)}</p>${table(['Research specification','Accuracy','Log loss','Brier','Games'],[['Previous selection',percent(a.previous.validation.accuracy),num(a.previous.validation.log_loss),num(a.previous.validation.brier),a.previous.validation.n],['New selection',percent(a.selected.validation.accuracy),num(a.selected.validation.log_loss),num(a.selected.validation.brier),a.selected.validation.n]])}</details>`:''}</section>`;
}
function outcomeLearningPanel(l){
 const a=l.lifecycle?.outcome_learning;if(!a)return '<p class="muted">Outcome learning checks verified results at each hourly update.</p>';
 return `<h4>Learning from results</h4><div class="record-metrics"><span>Settled results<strong>${a.settled_results}</strong></span><span>Correct picks<strong>${a.correct}</strong></span><span>Incorrect picks<strong>${a.incorrect}</strong></span></div><p class="muted">${esc(a.update_policy)}</p><details><summary>Largest unexpected outcomes</summary>${table(['Date','Matchup','Actual winner','Saved chance of winner','Pick result'],a.largest_surprises.map(e=>[e.date,e.home+' / '+e.away,e.winner,percent(e.winner_probability),e.correct?'Correct':'Incorrect']))}</details>`;
}
function renderModels(l){
 const r=l.benchmark;if(!r){$('model-content').innerHTML=empty('Model preparation','Historical results are collected daily. Initial validation requires at least 700 decisive results across 100 dates.')+`<section class="panel limits-panel"><h3>Features to investigate</h3><p class="muted">${esc(SPORT_INFO[league].needs)}</p><div class="feature-chips">${l.candidate_features.map(f=>'<span>'+esc(pretty(f))+'</span>').join('')}</div><p class="muted">Candidate inputs are a research plan, not features with demonstrated predictive benefit.</p></section>`;return;}
 const m=r.test;
 $('model-content').innerHTML=`<section class="panel"><h3>Active forecast model</h3><p><strong>${esc(pretty(l.lifecycle?.champion||r.selected))}</strong></p>${outcomeLearningPanel(l)}<p class="muted">Recent prediction results are in Prediction record. The benchmark below measures historical performance; research candidates do not change live forecasts until they pass the promotion checks.</p></section>`+`<section class="panel"><div class="section-heading"><div><p class="eyebrow">SEALED HISTORICAL TEST</p><h3>${esc(pretty(r.selected))}</h3><p class="muted">${esc(r.final_test_start)} → ${esc(r.last_date)} · ${m.n.toLocaleString()} evaluated events</p></div><span class="tag subdued">HISTORICAL BENCHMARK</span></div><div class="metric-grid">${[['Log loss',num(m.log_loss)],['Brier score',num(m.brier)],['Accuracy',percent(m.accuracy)],['ROC-AUC',num(m.roc_auc)],['Elo baseline Brier',num(r.baseline_test.brier)],['Brier 95% block interval',m.brier_week_block_bootstrap_95.map(x=>x.toFixed(3)).join(' – ')]].map(([label,value])=>`<div class="metric"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div><p class="muted">${esc(m.interval_note)}</p><p class="muted">${esc(r.calibration)} Daily checks leave these scores sealed; challenger improvements are evaluated separately below.</p></section><div class="two-cols limits-panel"><section class="panel"><p class="eyebrow">MODEL COMPARISON</p><h3>Candidate comparison</h3>${table(['Candidate','Mean validation log loss','Outcome'],r.candidates.map(c=>[pretty(c.name),num(c.mean_log_loss),c.name===r.selected?'Selected':c.status==='completed'?'Not selected':c.reason]))}<p class="muted">${esc(r.budget)}</p><details><summary>Expanding-fold dates and sample sizes</summary>${table(['Candidate','Train ends','Validation','n','Log loss'],r.candidates.flatMap(c=>(c.folds||[]).map(f=>[pretty(c.name),f.train_end,f.validation_start+' → '+f.validation_end,f.n,num(f.log_loss)])))}</details></section><section class="panel"><p class="eyebrow">PROBABILITY RELIABILITY</p><h3>Calibration</h3>${calibration(m.calibration)}${table(['Band','n','Mean forecast','Observed wins'],m.calibration.map(b=>[b.band.map(x=>Math.round(x*100)+'%').join('–'),b.n,percent(b.predicted),percent(b.observed)]))}<p class="muted">Points compare predicted and observed frequencies. Small bins are noisy; these are not confidence bounds for a single matchup.</p></section></div><section class="panel"><p class="eyebrow">PERFORMANCE BY SEASON</p><h3>Season performance</h3>${table(['Season','n','Log loss','Brier','Accuracy','ROC-AUC'],Object.entries(m.by_season||m.by_year).map(([year,s])=>[year,s.n,num(s.log_loss),num(s.brier),percent(s.accuracy),num(s.roc_auc)]))}<h4>Known limitations</h4><ul class="source-list">${r.limitations.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul><p class="audit-line">Benchmark dataset SHA-256<strong>${esc(r.dataset_sha256)}</strong></p><p class="audit-line">Champion weights last trained<strong>${esc(time(l.model_refitted_at))} · ${esc(l.model_training_rows||'—')} decisive results</strong></p><p class="audit-line">Current training dataset SHA-256<strong>${esc(l.model_training_sha256||'Not available')}</strong></p></section>`+`${l.name==='NBA'?'<details class="panel research-section"><summary>NBA improvement experiments</summary>'+nbaFocusPanel(l)+nbaTargetPanel(l)+nbaLearningPanel(l)+'</details>':''}<details class="panel research-section"><summary>Injury learning and outcome diagnostics</summary>${injuryLearningPanel(l)+diagnosticsPanel(l)}</details><details class="panel research-section"><summary>Challenger models and promotion checks</summary>${adaptivePanel(l)+reviewPanel(l)}</details>`;
}
function renderData(l){
 const teams=l.teams||[];
 $('data-content').innerHTML=`<div class="two-cols"><section class="panel"><p class="eyebrow">DATA COVERAGE</p><h3>Coverage and feed status</h3><p class="audit-line">Public result coverage<strong>${esc(l.data_from||'Not loaded')} → ${esc(l.data_through||'Not loaded')}</strong></p><p class="audit-line">Accepted final results<strong>${l.result_count.toLocaleString()}</strong></p><p class="audit-line">Source feed checked<strong>${esc(time(l.feed_checked))} · ${esc(l.feed_status)}</strong></p><p class="audit-line">Feed service<strong><a href="${safeLink(l.feed_provider)}" target="_blank" rel="noopener">${esc(l.feed_provider)}</a></strong></p><p class="muted">${esc(l.feed_type)}. ${l.feed_last_success?'Last successful connection: '+esc(time(l.feed_last_success)):''}</p>${l.feed_error?'<details><summary>Latest source check details</summary><p class="muted">'+esc(l.feed_error)+'</p></details>':''}<ul class="source-list">${l.sources.length?l.sources.map(s=>'<li>'+esc(s)+'</li>').join(''):'<li>No verified public result source loaded for this sport.</li>'}</ul><p class="muted">Only final results enter the core model. Rolling inputs precede the event date. Public exports exclude private uploads, account data and your personal prediction ledger.</p></section><section class="panel"><p class="eyebrow">SPORT-SPECIFIC RESEARCH</p><h3>Feature research</h3><p class="muted">${esc(SPORT_INFO[league].needs)}</p><div class="feature-chips">${l.candidate_features.map(f=>'<span>'+esc(pretty(f))+'</span>').join('')}</div><p class="muted">These candidate feature groups are not claimed to be available or validated. Current fitted baselines use historical outcomes, ratings, trailing margins, win rates and rest. Models stay separate by league.</p><p class="muted">Future inputs must be timestamped before the game, then tested with chronological validation and ablation before inclusion. Current results do not establish a universally best model.</p></section></div><section class="panel limits-panel"><p class="eyebrow">TEAM DATA / LAST 20 DECISIVE GAMES</p><h3>Team and fighter history</h3>${teams.length?(l.name==='UFC'?table(['Fighter','Prior fights','Latest fight','Trailing fights','Trailing wins'],teams.map(t=>[t.name,t.games,t.last_game,t.window_n,t.wins])):table(['Team','History n','Latest game','Rolling n','Rolling wins','Scored / game','Allowed / game','Margin / game'],teams.map(t=>[t.name,t.games,t.last_game,t.window_n,t.wins,t.scored_per_game.toFixed(2),t.allowed_per_game.toFixed(2),t.margin_per_game.toFixed(2)]))):empty('No team or fighter history loaded','A permitted historical source is required. No demonstration statistics are substituted.')}<p class="muted">Descriptive last-20-game summaries. The selected model may use a different validated window. Score margins are not opponent- or possession-adjusted efficiency. For UFC, only fight outcomes and layoff history are represented; the result encoding is not a fight score.</p></section><section class="panel"><p class="eyebrow">RECENT FINAL RESULTS</p><h3>Latest 20 imported events.</h3>${l.recent_results.length?table(['Source date','Home / first','Away / second','Final score','Outcome'],l.recent_results.map(g=>[g.date,g.home,g.away,l.name==='UFC'?('Winner: '+(g.outcome==='home'?g.home:g.outcome==='away'?g.away:pretty(g.outcome))):g.home_score+' – '+g.away_score,g.outcome])):empty('No real results to display','This sport is available as a separate dashboard view, but its historical data and validation are unfinished.')}<h4>Hourly pipeline</h4><p class="muted">${esc(snapshot.update_schedule)} Public data refresh → settle prior predictions → review losses → test a locked challenger → publish source-backed forecasts. A failed or stale source withholds current forecasts; it does not fabricate replacements. Historical benchmarks stay sealed.</p><p class="muted">Website content is an exported snapshot. Full private uploads, retraining controls and personal history live in the separately hosted Python app.</p></section>`;
}

let upcomingLimit=25;
function renderStatus(l){
 $('feed-overview').innerHTML=snapshot.leagues.map(s=>`<button type="button" data-feed-league="${esc(s.name)}" class="feed-tile ${s.name===league?'selected':''}"><b>${esc(s.name)}</b><span class="feed-state ${freshFeed(s)?'ready':''}">${freshFeed(s)?'Updated':s.feed_status==='unavailable'?'Checking source':'Update overdue'}</span><small>${s.result_count.toLocaleString()} results · ${fixtures(s).length} fixtures</small></button>`).join('');
 const c=l.lifecycle;
 $('model-status').innerHTML=`<div class="section-heading"><div><h3>${c?'Model update checks':'Daily collection'}</h3><p class="muted">${esc(c?c.status:'Results and schedules refresh hourly. Model validation begins when enough history is available.')}</p></div><span class="tag subdued">${freshFeed(l)?'Feed updated':'Feed check pending'}</span></div>${c?`<div class="lifecycle-stats"><span>Weights through <b>${esc(c.weights_trained_through)}</b></span><span>Tracked picks · ${esc(c.feedback_policy||'legacy')} <b>${c.live_record.wins} correct · ${c.live_record.losses} missed · ${c.live_record.pending} pending${c.feedback_report?.metrics?' · '+percent(c.feedback_report.metrics.accuracy)+' correct':''}</b></span><span>Promotion <b>Backtest improvement required</b></span></div><details><summary>Review policy and evidence</summary><p class="muted">${esc(c.policy.description)} At least ${c.policy.minimum_results} new results across ${c.policy.minimum_weeks} calendar weeks; log-loss improvement ≥ ${c.policy.minimum_log_loss_gain}; Brier and accuracy cannot worsen. The first exported pre-event picks are retained for scoring.</p>${c.confirmation?table(['Confirmation sample','Weeks','Decision'],[[c.confirmation.n,c.confirmation.weeks,c.confirmation.status]]):''}${c.last_decision?table(['Model','Log loss','Brier','Accuracy'],[['Prior champion',num(c.last_decision.champion.log_loss),num(c.last_decision.champion.brier),percent(c.last_decision.champion.accuracy)],['Challenger',num(c.last_decision.challenger.log_loss),num(c.last_decision.challenger.brier),percent(c.last_decision.challenger.accuracy)]]):''}<p class="muted">Fresh results update model inputs hourly. Weights stay fixed while a challenger collects independent evidence. A missed favorite alone does not justify retraining.</p></details>`:''}`;
 if(l.name==='NBA'){const i=l.injury_research;const n=i?.recorded;$('model-status').innerHTML+=`<p class="muted">NBA injury recording · ${typeof n==='number'?n+' pregame snapshots saved':'snapshot counters pending publication'} · ${i?.settled_all??i?.settled??0} settled · injury effects not yet approved in win probabilities. See Model lab for evidence.</p>`;}
 const upcomingOpen=$('all-upcoming-list')?.open||false;
 const schedule=dayEvents(l).filter(p=>(!dateFilter||eventDay(p)===dateFilter)&&(!teamFilter||(p.home+' '+p.away).toLowerCase().includes(teamFilter.toLowerCase())));
 $('schedule-content').innerHTML='<h3>Schedule · '+esc(dayLabel(dateFilter))+'</h3><p class="muted">Upcoming fixtures come from published schedules; saved picks and final grades are in Right / wrong. Pre-event probabilities expire at game time. This is an hourly snapshot, not a live scoreboard.</p>'+ (schedule.length?table(['Start','Home / first opponent','Away / second opponent'],schedule.slice(0,10).map(p=>[p.start_time?time(p.start_time):p.date,p.home,p.away]))+(schedule.length>10?'<details><summary>Show '+(schedule.length-10)+' more fixtures</summary>'+table(['Start','Home / first','Away / second'],schedule.slice(10).map(p=>[p.start_time?time(p.start_time):p.date,p.home,p.away]))+'</details>':''):'<p class="muted">No fixtures returned for this day. Try another date; future schedules depend on the source publishing them.</p>')+(l.recent_results.length?'<details><summary>Recent final results · source dates, separate from selected day</summary>'+table(['Date','Home / first','Away / second','Result'],l.recent_results.slice(0,8).map(r=>[r.date,r.home,r.away,l.name==='UFC'?(r.outcome==='home'?r.home:r.outcome==='away'?r.away:pretty(r.outcome)):r.home_score+' – '+r.away_score]))+'</details>':'');
 const upcoming=fixtures(l).filter(p=>!teamFilter||(p.home+' '+p.away).toLowerCase().includes(teamFilter.toLowerCase())).sort((a,b)=>String(a.start_time||a.date).localeCompare(String(b.start_time||b.date)));
 $('schedule-content').innerHTML+=`<details id="all-upcoming-list" ${upcomingOpen?'open':''}><summary>All published upcoming games · ${upcoming.length}</summary><p class="muted">Published fixtures for the coming year, as available from the source. ${l.future_schedule_error?'Full-season source check is pending; showing the verified fixtures currently available. ':''}Model forecasts cover the next 14 days when validated inputs are available; other dates remain schedule-only.</p>${table(['Date / time','Home','Away','Availability'],upcoming.slice(0,upcomingLimit).map(p=>[p.start_time?time(p.start_time):p.date+' · time TBD',p.home,p.away,p.forecast_eligible===false?(p.schedule_note?'Schedule only · '+p.schedule_note:'Schedule only'):p.date>shiftDay(localDay(),14)?'Schedule only · forecasts nearer game time':'Forecasts subject to data readiness']))}${upcoming.length>upcomingLimit?'<button type="button" id="more-upcoming">Show 25 more</button><button type="button" id="all-upcoming">Show all published games</button>':''}</details>`;
}
$('schedule-content').onclick=e=>{if(e.target.closest('#more-upcoming')){upcomingLimit+=25;renderStatus(current());}else if(e.target.closest('#all-upcoming')){upcomingLimit=Infinity;renderStatus(current());}};
$('feed-overview').onclick=e=>{const b=e.target.closest('[data-feed-league]');if(b){league=b.dataset.feedLeague;selected=null;teamFilter='';allSports=true;$('team-filter').value='';render();}};

async function load(){
 $('refresh').disabled=true;$('error').hidden=true;
 try{const r=await fetch(new URL('./web/data/snapshot.json',document.baseURI),{cache:'no-cache'});if(!r.ok)throw Error('Model snapshot could not be loaded (HTTP '+r.status+').');const next=await r.json();if(next.schema_version!==1||!Array.isArray(next.leagues))throw Error('Unsupported model snapshot.');snapshot=next;render();}
 catch(e){$('loading').hidden=true;$('error').textContent=e.message+' No substitute statistics or probabilities are shown.';$('error').hidden=false;}
 finally{$('refresh').disabled=false;}
}
$('sports').onclick=e=>{const b=e.target.closest('[data-league]');if(!b)return;league=b.dataset.league;selected=null;teamFilter='';$('team-filter').value='';try{localStorage.setItem('courtside_public_league',league);}catch(_){}render();};
document.querySelector('.view-tabs').onclick=e=>{const b=e.target.closest('[data-view]');if(!b)return;view=b.dataset.view;render();};
$('matchups').onclick=e=>{const b=e.target.closest('[data-fixture]');if(!b)return;selected=b.dataset.fixture;render();};
$('team-filter').oninput=()=>{teamFilter=$('team-filter').value;render();};
$('date-filter').onchange=()=>chooseDay($('date-filter').value);
$('previous-day').onclick=()=>chooseDay(shiftDay(dateFilter,-1));$('next-day').onclick=()=>chooseDay(shiftDay(dateFilter,1));
$('yesterday').onclick=()=>chooseDay(shiftDay(localDay(),-1));$('today').onclick=()=>chooseDay(localDay());$('tomorrow').onclick=()=>chooseDay(shiftDay(localDay(),1));
$('future-dates').onchange=()=>{if($('future-dates').value){view='forecasts';chooseDay($('future-dates').value);}};
