for(const id of ['prop-search','prop-line'])$(id).oninput=renderProps;
$('prop-add').onclick=()=>{const sport=$('prop-sport').value,player=snapshot.player_props?.leagues?.[sport]?.players.find(p=>p.id===$('prop-player').value);if(!player)return;const item={sport,player:player.name,player_id:player.id,market:$('prop-market').value,line:Number($('prop-line').value),side:$('prop-side').value,saved:new Date().toISOString()};if(!Number.isFinite(item.line)||item.line<0||!$('prop-line').value)return;if(!propSaved.some(p=>p.sport===sport&&p.player_id===item.player_id&&p.market===item.market&&p.line===item.line&&p.side===item.side))propSaved.push(item);try{localStorage.setItem('courtside_prop_shortlist',JSON.stringify(propSaved));}catch(_){}renderPropShortlist();};
$('prop-shortlist').onclick=e=>{const b=e.target.closest('[data-remove-prop]');if(!b)return;propSaved.splice(Number(b.dataset.removeProp),1);try{localStorage.setItem('courtside_prop_shortlist',JSON.stringify(propSaved));}catch(_){}renderPropShortlist();};

let finderCandidates=[];
function renderFinder(){
 const sport=$('finder-sport').value,previous=$('finder-game').value;
 const sources=snapshot.leagues.filter(l=>sport==='all'||l.name===sport).filter(l=>snapshot.player_props?.leagues?.[l.name]).map(l=>({sport:l.name,fixtures:freshFeed(l)?(l.schedule||[]).filter(f=>eventDay(f)===dateFilter&&Date.parse(f.start_time)>Date.now()):[],...snapshot.player_props.leagues[l.name],injuryReport:snapshot.injuries?.leagues?.[l.name]}));
 const games=sources.flatMap(s=>s.fixtures.map(f=>({...f,sport:s.sport})));
 $('finder-game').innerHTML='<option value="all">All games on selected day</option>'+games.map(f=>`<option value="${esc(f.sport+':'+f.id)}">${esc(f.sport)} · ${esc(f.away)} at ${esc(f.home)} · ${esc(time(f.start_time))}</option>`).join('');
 if(games.some(g=>g.sport+':'+g.id===previous))$('finder-game').value=previous;
 const before=$('finder-market').value,markets=[...new Set(sources.flatMap(s=>(s.players||[]).flatMap(p=>p.games.flatMap(g=>Object.keys(g.values)))))].filter(m=>PROP_LINES[m]).sort();
 $('finder-market').innerHTML='<option value="all">All statistics</option>'+markets.map(m=>`<option>${esc(m)}</option>`).join('');if(markets.includes(before))$('finder-market').value=before;
 const selectedGame=$('finder-game').value,selectedSources=sources.map(s=>({...s,fixtures:s.fixtures.filter(f=>selectedGame==='all'||s.sport+':'+f.id===selectedGame)}));
 const selectedGames=selectedSources.flatMap(s=>s.fixtures);
 const shortlist=()=>{$('finder-shortlist').innerHTML=propSaved.length?propSaved.map((p,i)=>`<div class="prop-saved"><span>${esc(p.sport)} · ${esc(p.player)} · ${esc(p.side)} ${esc(p.line)} ${esc(p.market)}</span><button type="button" data-finder-remove="${i}">Remove</button></div>`).join(''):empty('No saved suggestions','Save candidates from the list above.');};
 if(!selectedGames.length){finderCandidates=[];$('finder-summary').textContent='No verified upcoming games on '+dayLabel(dateFilter)+'. Choose another date above or another sport.';$('finder-results').innerHTML='';shortlist();return;}
 if(selectedGames.every(f=>Date.parse(f.start_time)-Date.now()>14*86400000)){finderCandidates=[];$('finder-summary').textContent='Published schedule available. Prop research opens within 14 days of these games.';$('finder-results').innerHTML='';shortlist();return;}
 const freshSources=selectedSources.filter(s=>Date.now()-Date.parse(s.checked)>=0&&Date.now()-Date.parse(s.checked)<=86400000),skipped=selectedSources.filter(s=>s.fixtures.length&&!freshSources.includes(s)).map(s=>s.sport);
 const requested=$('finder-count').value.trim(),count=Number(requested);
 if(requested!=='all'&&(!Number.isSafeInteger(count)||count<1)){$('finder-summary').textContent='Enter a positive whole number, or choose Show all available.';$('finder-results').innerHTML='';shortlist();return;}
 finderCandidates=findDailyProps(freshSources,{minimum:Number($('finder-min').value),minGames:Number($('finder-sample').value),side:$('finder-side').value,market:$('finder-market').value,perfectOnly:$('finder-perfect').checked});
 const shown=requested==='all'?finderCandidates:finderCandidates.slice(0,count);
 $('finder-summary').textContent=`${shown.length} shown · ${finderCandidates.length} qualifying props across ${selectedGames.length} upcoming games · ${dayLabel(dateFilter)}. Ranked by evidence lower bound, then consistency estimate. ${requested!=='all'&&count>finderCandidates.length?'Fewer candidates qualify than requested. ':''}${skipped.length?'Fresh player collection needed: '+skipped.join(', ')+'. ':''}${freshSources.filter(s=>s.error).map(s=>s.sport+': '+s.error).join(' ')}`;
 $('finder-results').innerHTML=shown.length?'<p class="muted">Automatically suggested alternate lines · verify availability and active players. Estimates describe historical consistency, not a validated chance of winning. Multiple props can be correlated.</p><div class="finder-cards">'+shown.map((p,i)=>`<article class="panel finder-card"><div class="card-foot"><span>#${i+1} · ${esc(p.sport)} · ${esc(p.team)}</span><strong>${percent(p.score)} consistency estimate</strong></div><h4>${esc(p.player)}</h4><p class="finder-pick">${esc(pretty(p.side))} ${p.line} ${esc(p.market)}</p><p>${esc(p.matchup)} · ${esc(time(p.start_time))}</p><p class="muted">Availability: ${esc(p.availability.status)}</p><p><strong>${percent(p.hits/p.n)} observed · ${p.hits}/${p.n}</strong> collected hits · last 5: ${p.recentHits}/${p.recentN} · streak: ${p.streak}</p><p class="muted">Evidence lower bound: ${percent(p.lower)} · ${p.n<10?'Small sample · ':''}latest appearance ${esc(time(p.latest))}. Collection checked ${esc(time(p.checked))}.</p><button type="button" data-finder-save="${finderCandidates.indexOf(p)}">Save suggestion</button><details><summary>Inspect supporting results</summary>${table(['Game time','Value','Result'],p.observations.map(g=>[time(g.start_time),g.values[p.market],(p.side==='over'?g.values[p.market]>p.line:g.values[p.market]<p.line)?'Hit':'Miss']))}<a href="${safeLink(p.observations[0].source)}" target="_blank" rel="noopener">Latest source box score ↗</a></details></article>`).join('')+'</div>':empty('No candidates meet these settings','Fresh injury coverage and player data are required. Reported out, doubtful, questionable and other uncertain players are excluded. Try another day or adjust the statistical filters. No extra suggestions are invented.');
 shortlist();
}
for(const id of ['finder-sport','finder-game','finder-min','finder-sample','finder-side','finder-market','finder-perfect'])$(id).onchange=renderFinder;
$('finder-count').oninput=renderFinder;$('finder-run').onclick=renderFinder;
$('finder-all').onclick=()=>{$('finder-count').type='text';$('finder-count').value='all';renderFinder();};
$('finder-count').onfocus=()=>{if($('finder-count').value==='all'){$('finder-count').type='number';$('finder-count').value='10';}};
$('finder-results').onclick=e=>{const button=e.target.closest('[data-finder-save]');if(!button)return;const p=finderCandidates[Number(button.dataset.finderSave)];if(!p)return;const sport=p.sport;if(!propSaved.some(s=>s.sport===sport&&s.player_id===p.player_id&&s.market===p.market&&s.side===p.side&&s.line===p.line))propSaved.push({sport,player:p.player,player_id:p.player_id,market:p.market,line:p.line,side:p.side,event_id:p.event_id,saved:new Date().toISOString()});try{localStorage.setItem('courtside_prop_shortlist',JSON.stringify(propSaved));}catch(_){}renderFinder();};
$('finder-shortlist').onclick=e=>{const b=e.target.closest('[data-finder-remove]');if(!b)return;propSaved.splice(Number(b.dataset.finderRemove),1);try{localStorage.setItem('courtside_prop_shortlist',JSON.stringify(propSaved));}catch(_){}renderFinder();};

function injuryPanel(report,home,away){
 const current=report?.status==='ok'&&Date.parse(report.checked)<=Date.now()&&Date.now()<Date.parse(report.valid_until);
 const players=[...(report?.teams?.[home]||[]),...(report?.teams?.[away]||[])];
 return `<section class="injury-context"><h4>Injuries & availability</h4><p class="muted">${current?'Report checked '+esc(time(report.checked)):'Fresh injury coverage is unavailable.'} · ${esc(home)} / ${esc(away)}. A missing name does not confirm a player is active or starting.</p>${players.length?'<details><summary>View '+players.length+' reported players</summary>'+table(['Team','Player','Status','Position','Reported'],players.map(p=>[p.team,p.player,p.status,p.position,time(p.reported_at)]))+'</details>':'<p class="muted">No usable listed-player records for these teams. This is not a confirmed healthy lineup.</p>'}<p class="muted">The displayed team probability remains a result-history baseline. Injury effects have not yet passed prospective model validation; no arbitrary percentage adjustment is applied.</p>${report?.source?`<a href="${safeLink(report.source)}" target="_blank" rel="noopener">Injury report source ↗</a>`:''}</section>`;
}
function explainPrediction(p,l){
 if(!p)return '<h3>Why this team?</h3><p class="muted">Select an available matchup to see why the fitted model favors a team, the recent performance context and reported injuries.</p>';
 const home=p.home_probability>=.5,winner=home?p.home:p.away,other=home?p.away:p.home,prob=home?p.home_probability:p.away_probability;
 const labels={elo_difference:'relative team strength',home_advantage:'the home venue',win_rate_difference:'recent win rate',scoring_margin_difference:'recent scoring margin',rest_difference:'sport-adjusted rest',uncertainty_adjusted_log_odds:'uncertainty-adjusted team ratings'};
 const supports=(p.factors||[]).filter(f=>typeof f.log_odds_contribution==='number'&&f.log_odds_contribution*(home?1:-1)>0).sort((a,b)=>Math.abs(b.log_odds_contribution)-Math.abs(a.log_odds_contribution)).slice(0,3);
 const explanation=supports.length?`The strongest displayed fitted contributions supporting ${esc(winner)} are ${supports.map(f=>esc(labels[f.factor]||pretty(f.factor))).join(', ')}. These are model associations, not proof that a factor caused a win.`:'This fitted model combines historical team ratings and rolling results. It does not expose a reliable individual contribution breakdown, so specific inputs are not presented as proven causes.';
 const teams=[winner,other].map(name=>(l.teams||[]).find(t=>t.name===name)).filter(Boolean);
 return `<h3>Why ${esc(winner)}?</h3><p><strong>${esc(winner)} ${percent(prob)}</strong> versus ${esc(other)} ${percent(1-prob)}. ${prob<.6?'This is a narrow lean, so an upset would not be surprising.':'The other team still has a meaningful chance to win.'}</p><p>${explanation}</p>${teams.length?'<h4>Recent team context</h4>'+table(['Team','Recent games','Wins','Points / runs / goals scored per game','Average margin'],teams.map(t=>[t.name,t.window_n,t.wins,typeof t.scored_per_game==='number'?t.scored_per_game.toFixed(1):'—',typeof t.margin_per_game==='number'?t.margin_per_game.toFixed(1):'—']))+'<p class="muted">These summaries describe recent results; they are not a causal explanation or injury-adjusted projection.</p>':''}${injuryPanel(l.injuries,p.home,p.away)}<p class="muted">A favorite can lose. Historical backtest accuracy and the actual saved prediction record are separate measures.</p>`;
}
function recordOverview(l){
 const picks=history(l),c=predictionCounts(picks);
 return `<div class="record-heading"><div><h3>How have the predictions done?</h3><p class="muted">${esc(l.name)} · last 7 calendar days, including today. One saved pick per game: current eligible policy when available, otherwise the first valid saved version. Original policies remain available in the audit table.</p></div><button id="open-record" type="button">See right / wrong record</button></div><div class="record-metrics"><span><strong>${c.correct}</strong> Correct</span><span><strong>${c.incorrect}</strong> Incorrect</span><span><strong>${c.pending}</strong> Pending / in progress</span><span><strong>${c.awaiting}</strong> Awaiting source result</span><span><strong>${c.unscored}</strong> Unscored</span><span><strong>${c.graded?percent(c.accuracy):'—'}</strong> Observed accuracy</span></div><p class="muted">Accuracy = correct ÷ graded games (${c.graded}). Delayed source results, unfinished games and unscored events are separate; none is counted as a win or loss until verified.</p>`;
}
$('record-overview').onclick=e=>{if(e.target.closest('#open-record')){view='history';render();}};

function adaptivePanel(l){
 const r=l.lifecycle?.adaptive_review;if(!r)return '';
 if(!r.incumbent)return `<section class="panel limits-panel"><h3>Continuous improvement research</h3><p class="muted">${esc(r.status)} · ${esc(r.error||'Waiting for comparable development history.')}</p></section>`;
 const trial=l.lifecycle?.adaptive_trial,modern=r.recent_data_research;
 const row=(name,v)=>[name,percent(v.accuracy),num(v.log_loss),num(v.brier),v.n];
 const tested=(r.candidates||[]).filter(c=>c.specification.variant==='context_feedback'&&c.validation).sort((a,b)=>b.validation.accuracy-a.validation.accuracy||a.validation.log_loss-b.validation.log_loss);
 return `<section class="panel limits-panel"><h3>Continuous improvement research</h3><p>${r.new_candidates} fixed adaptive, calibration and blend candidates · ${esc(r.new_method_selected?'New method qualifies in development':'Prior research winner retained')}. This is research evidence, not a live accuracy gain.</p>${table(['Specification','Accuracy','Log loss','Brier','Events'],[row('Prior research winner',r.incumbent.validation),...tested.slice(0,3).map(c=>row(pretty(c.name),c.validation))])}<p class="muted">${esc(r.note)} Development ends ${esc(r.development_through)}; the original final test is excluded. A candidate must preserve accuracy and Brier while lowering log loss against the prior research winner.</p>${modern?.incumbent?`<details><summary>Modern NBA development check</summary>${table(['Specification','Accuracy','Log loss','Brier','Events'],[row('Retained modern feedback specification',modern.incumbent.validation),row('Selected after new search',modern.best.validation)])}<p class="muted">${esc(modern.note)}</p></details>`:''}<p>Automatic loop: hourly data refresh → score immutable picks → diagnose losses → run cached bounded studies → lock a qualifying challenger after a loss → test on new dates.</p><p class="muted">${trial?esc(trial.status)+' · '+esc(pretty(trial.selected))+(trial.confirmation?' · '+trial.confirmation.n+' new results / '+trial.confirmation.weeks+' weeks':''):(r.new_method_selected?'Development candidate qualifies; hourly loss review can lock an independent trial.':'No new adaptive challenger has qualified for an independent trial.')} Production still requires at least 100 new results across 8 weeks, better log loss, non-worse Brier/accuracy, and the paired weekly confidence check. Ongoing trials are not replaced by a new search.</p></section>`;
}
function diagnosticsPanel(l){
 const d=l.lifecycle?.feedback_report?.diagnostics;if(!d?.n)return '';
 const drift=d.drift,c=d.calibration;
 return `<section class="panel limits-panel"><h3>Learning from prediction errors</h3><p>${d.n} actual saved and settled picks across all tracked dates · drift monitor: ${esc(drift.status)}. Monitoring identifies patterns to investigate, not proven reasons a team lost.</p>${d.rolling.length?table(['Most recent picks','Accuracy','Log loss','Brier','Mean confidence','Confidence − accuracy','75%+ favorites missed'],d.rolling.map(r=>[r.n,percent(r.accuracy),num(r.log_loss),num(r.brier),percent(r.mean_confidence),percent(r.confidence_gap),r.high_confidence_misses])):'<p class="muted">Rolling summaries start after ten settled predictions.</p>'}${drift.recent?`<p class="muted">Latest 50 vs preceding 50 log-loss change: ${num(drift.log_loss_change)} (positive is worse). ${drift.weekly_log_loss_change_95?'Weekly block 95% interval: '+drift.weekly_log_loss_change_95.map(num).join(' to '):'Not enough calendar-week evidence for a block interval.'}</p>`:''}${d.actions.length?'<ul>'+d.actions.map(a=>'<li>'+esc(a)+'</li>').join('')+'</ul>':''}<details><summary>Team, venue and calibration diagnostics</summary>${table(['Favorite venue','Picks','Accuracy','Log loss','Confidence gap'],d.venues.map(v=>[v.group,v.n,percent(v.accuracy),num(v.log_loss),percent(v.confidence_gap)]))}${table(['Team involved · minimum 3 picks','Picks','Accuracy','Log loss'],d.teams.map(t=>[t.team,t.n,percent(t.accuracy),num(t.log_loss)]))}${c?table(['Probability diagnostic','Value'],[['Binned calibration error',num(c.expected_calibration_error)],['Binned reliability',num(c.binned_reliability)],['Binned resolution',num(c.binned_resolution)],['Outcome uncertainty',num(c.outcome_uncertainty)],['Within-bin decomposition residual',num(c.binning_residual)]]):''}<p class="muted">${esc(c?.note||'')} ${esc(d.note)}</p></details></section>`;
}

function nbaFocusPanel(l){
 const r=l.lifecycle?.adaptive_review?.nba_focus_research;if(l.name!=='NBA'||!r?.incumbent)return '';
 const c=r.confirmation,accepted=r.new_method_selected&&c?.passed;
 const row=(label,v)=>[label,percent(v.accuracy),num(v.log_loss),num(v.brier),v.n];
 return `<section class="panel limits-panel"><h3>NBA model development</h3><p>${r.new_candidates} focused season-context, uncertainty, calibration and blend candidates. ${accepted?'Candidate passed historical checks; future validation is still required.':'Retained NBA candidate kept; the new study did not pass every check.'}</p>${table(['Development specification','Accuracy','Log loss','Brier','Games'],[row('Retained feedback specification',r.incumbent.validation),row('Development-selected candidate',r.best.validation)])}${c?'<h4>Historical follow-up check · same games</h4>'+table(['Specification','Accuracy','Log loss','Brier','Games'],[row('Retained feedback specification',c.previous.validation),row('Development-selected candidate',c.selected.validation)])+'<p class="muted">'+esc(c.passed?'Passed historical probability and accuracy checks.':'Rejected: the selected candidate did not improve all required measures.')+'</p>':''}<p class="muted">${esc(r.note)} A development gain alone does not update live weights.</p></section>`;
}
function injuryLearningPanel(l){
 if(l.name!=='NBA')return '';
 const i=l.injury_research||{},report=l.injuries||{},listed=Object.values(report.teams||{}).reduce((n,p)=>n+p.length,0),value=x=>typeof x==='number'?x:'—';
 return `<section class="panel limits-panel"><h3>NBA injury learning</h3><p>Source checked ${esc(time(report.checked))} · ${listed} listed players · ${esc(report.status||'unverified')}. Reports are refreshed hourly and archived with timestamps.</p><div class="record-metrics"><span><strong>${value(i.recorded)}</strong> Pregame snapshots saved</span><span><strong>${value(i.pending)}</strong> Awaiting results</span><span><strong>${value(i.settled_all??i.settled)}</strong> Settled snapshots</span><span><strong>${value(i.archive_reports)}</strong> Archived reports</span></div><p>Player-aware recording adds prior observed points, rebounds and assists represented by listed absences, with separate uncertain-player and missing-data indicators. These are production proxies, not point penalties or confirmed starter values.</p><p><strong>${value(i.records_with_player_production)} player-aware snapshots saved.</strong> Current recorded schema: ${esc(i.feature_schema||'Awaiting counter publication')}. First observations are never rewritten to add later information.</p><p class="muted">${i.feature_schema==='nba-production-v2'?value(i.settled)+' / '+(i.minimum_settled||200)+' settled player-aware games available for the first chronological comparison.':'The new player-aware cohort begins with new eligible pregame captures and needs 200 settled games. Earlier count-only history stays preserved.'} Active-schema records: ${value(i.training_recorded)}; preserved records outside that schema: ${value(i.excluded_legacy_schema)}. Live win probabilities are not injury-adjusted yet.</p>${i.recent_captures?.length?'<details><summary>Inspect recent first-observed pregame captures</summary>'+table(['Matchup','First observed','Event start','Feature schema','Outcome'],i.recent_captures.map(r=>[r.home+' / '+r.away,time(r.observed_at),time(r.event_start_utc),r.feature_schema||'injury-counts-v1',r.outcome===1?'Home won':r.outcome===0?'Away won':r.grading_status==='unscored'?'Unscored':'Pending']))+'</details>':''}</section>`;
}

let perfectLimit=50;
function renderPerfectProps(){
 const selectedSport=$('perfect-sport').value,sample=Number($('perfect-sample').value),market=$('perfect-market').value,query=$('perfect-search').value.trim().toLowerCase();
 const sources=Object.entries(snapshot.player_props?.leagues||{}).filter(([sport])=>selectedSport==='all'||sport===selectedSport);
 const markets=[...new Set(sources.flatMap(([,data])=>(data.players||[]).flatMap(p=>p.games.flatMap(g=>Object.keys(g.values)))))].filter(m=>PROP_LINES[m]).sort();
 $('perfect-market').innerHTML='<option value="all">All statistics</option>'+markets.map(m=>`<option>${esc(m)}</option>`).join('');if(markets.includes(market))$('perfect-market').value=market;
 const records=[],unavailable=[];
 for(const [sport,data] of sources){
  const checked=Date.parse(data.checked),valid=checked+86400000;
  if(!Number.isFinite(checked)||checked>Date.now()||!Number.isFinite(valid)||Date.now()>=valid){unavailable.push(sport);continue;}
  records.push(...findPerfectProps(data.players||[],{sample,side:$('perfect-side').value,market:$('perfect-market').value,injuryReport:snapshot.injuries?.leagues?.[sport]}).filter(p=>!query||p.player.toLowerCase().includes(query)).map(p=>({...p,sport,checked:data.checked})));
 }
 records.sort((a,b)=>b.lower-a.lower||a.sport.localeCompare(b.sport)||a.player.localeCompare(b.player)||a.market.localeCompare(b.market));
 const shown=records.slice(0,perfectLimit);
 $('perfect-summary').textContent=`${shown.length} shown / ${records.length} qualifying player-statistic results · all teams · ${sample}/${sample} required.${unavailable.length?' Fresh collection needed: '+unavailable.join(', ')+'.':''}`;
 $('perfect-results').innerHTML=shown.length?'<div class="finder-cards">'+shown.map(p=>`<article class="panel finder-card"><div class="card-foot"><span>${esc(p.sport)} · ${esc(p.team)}</span><strong>100% observed · ${p.hits}/${p.n}</strong></div><h4>${esc(p.player)}</h4><p class="finder-pick">${esc(pretty(p.side))} ${p.line} ${esc(p.market)}</p><p>Sample: ${esc(time(p.observations.at(-1).start_time))} → ${esc(time(p.latest))}</p><p class="muted">Shrunk consistency estimate: ${percent(p.score)} · evidence lower bound: ${percent(p.lower)}. These are historical summaries.</p><p class="muted">Availability: ${esc(p.availability.status)} · latest observed team shown.</p><p class="muted">Collection checked ${esc(time(p.checked))}</p><details><summary>Inspect all ${p.n} collected results</summary>${table(['Game time','Value','Result'],p.observations.map(g=>[time(g.start_time),g.values[p.market],'Hit']))}</details></article>`).join('')+'</div>':empty('No 100% records match these filters','Try another sample window or statistic. Players need the full selected number of collected observations; missing results are never invented.');
 $('perfect-more').hidden=records.length<=perfectLimit;
}
for(const id of ['perfect-sport','perfect-sample','perfect-side','perfect-market'])$(id).onchange=()=>{perfectLimit=50;renderPerfectProps();};
$('perfect-search').oninput=()=>{perfectLimit=50;renderPerfectProps();};
$('perfect-more').onclick=()=>{perfectLimit+=50;renderPerfectProps();};
